mapper.select:
SELECT o.id,o.order_no, o.user_id, u.nickname AS userNickname, o.status, o.total_amount, o.pay_amount, o.pay_time, o.ship_time, o.receive_time, o.receiver_name, o.receiver_phone, o.receiver_addr, o.create_time FROM t_order o LEFT JOIN t_user u ON u.id = o.user_id
WHERE 1 = 1
AND o.status = #{status}
AND o.user_id = #{userId}
AND ( o.order_no LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR EXISTS (SELECT 1 FROM t_order_item i WHERE i.order_no = o.order_no AND i.product_name LIKE CONCAT('%', #{keyword}, '%')) )
ORDER BY o.create_time DESC

SELECT id, order_no, track_no, current_status, current_node, estimated_arrival, update_time
FROM t_order_logistics
WHERE order_no = #{orderNo}

SELECT id, order_id, order_no, product_id, product_name, product_price, quantity, refund_deadline FROM t_order_item WHERE order_no IN
#{no}
ORDER BY order_no, id

SELECT status, COUNT(*) AS n FROM t_order WHERE 1 = 1
AND user_id = #{userId}
GROUP BY status
